import os, subprocess

PID = "/content/job.pid"
alive = False
if os.path.exists(PID):
    try:
        os.kill(int(open(PID).read().strip()), 0)    # signal 0 = existence check
        alive = True
    except Exception:
        alive = False

if alive:
    print("ALREADY_RUNNING")
elif os.path.exists("/content/out/result.json"):
    print("ALREADY_DONE")
else:
    cmd = ("cd /content && setsid nohup python3 job.py > /content/job.out 2>&1 < /dev/null & "
           "echo $! > /content/job.pid; cat /content/job.pid")
    p = subprocess.run(["bash", "-lc", cmd], capture_output=True, text=True)
    print("LAUNCHED", p.stdout.strip())
